// Tres necesidades de replicación de S3 y el mecanismo elegido para cada una. Dos están mal asignadas: corrígelas.
// Mecanismos: "replicacion-en-vivo", "s3-batch-replication", "s3-rtc" y "crr".
export const diseno = {
  casos: [
    { necesidad: "replicar-los-objetos-que-ya-existian-antes-de-configurar-la-replicacion", mecanismo: "replicacion-en-vivo" },
    { necesidad: "replicar-los-objetos-nuevos-en-un-plazo-predecible-de-15-minutos-con-sla", mecanismo: "s3-batch-replication" },
    { necesidad: "copiar-objetos-a-un-bucket-de-otra-region-distante-por-cumplimiento", mecanismo: "crr" },
  ],
};

